#!/bin/sh
# make_board_backup.sh -- pack the board-only sources/data that have no host master.
#
# Excluded on purpose (all reproducible or worthless):
#   *.pyc / __pycache__      regenerated on import
#   *.so, compiled binaries  rebuilt on the board from the .c sources
#   *.b64, *.gz              leftovers of earlier serial transfers
#   *.bak, *.orig, *.pre_*   duplicates of files we already have
#   *.bit, *.bit.bin, *.xsa  regenerated by Vivado, and already in the host tree
#   *.bin weights            way too big for serial, and not lost (still on SD)
#
# What is kept:
#   *.c *.h                  kernel sources including driver/tokenizer
#   *.py                     engine, drivers, tools
#   *.sh                     board scripts
#   *.tcl                    Vivado batch scripts found on the board
#   *.json                   vocab remap tables (old_to_new_64k / new_to_old_64k)
#   *.txt *.log              evidence logs
#   mount_and_run.sh         boot helper

cd /mnt/qwen || exit 1

OUT=/mnt/qwen/board_backup.tar.gz
LIST=/tmp/backup_list.txt

find . -type f \
    ! -name '*.pyc' \
    ! -name '*.so' \
    ! -name '*.b64' \
    ! -name '*.gz' \
    ! -name '*.bak' \
    ! -name '*.orig' \
    ! -name '*.pre_opt' \
    ! -name '*.pre_attn' \
    ! -name '*.failed_exp' \
    ! -name '*.bit' \
    ! -name '*.bit.bin' \
    ! -name '*.xsa' \
    ! -name '*.bin' \
    ! -name '*.npy' \
    ! -path '*/__pycache__/*' \
    ! -path './System Volume Information/*' \
    \( -name '*.c' -o -name '*.h' -o -name '*.py' -o -name '*.sh' \
       -o -name '*.tcl' -o -name '*.json' -o -name '*.txt' -o -name '*.log' \
       -o -name '*.md' -o -name 'expected.md5' \) \
    > "$LIST"

echo "files selected: $(wc -l < "$LIST")"
echo "uncompressed:   $(du -ch $(cat "$LIST" | tr '\n' ' ') 2>/dev/null | tail -1 | cut -f1)"

rm -f "$OUT"
tar -czf "$OUT" -T "$LIST" 2>/dev/null
if [ ! -f "$OUT" ]; then
    echo "ERROR: tar failed"
    exit 1
fi

echo "archive:        $OUT"
ls -l "$OUT" | awk '{print "size:           " $5 " bytes"}'
echo "md5:            $(md5sum "$OUT" | cut -d' ' -f1)"
echo ""
echo "=== largest 12 entries ==="
tar -tzvf "$OUT" 2>/dev/null | sort -k3 -n -r | head -12 | awk '{printf "  %10s  %s\n", $3, $6}'
